const assert = require('node:assert/strict');
const fs = require('node:fs');
const crypto = require('node:crypto');
const out = '/t/out-' + process.versions.node.split('.')[0];
const mode = path => fs.statSync(path).mode & 0o777;
const hash = path => crypto.createHash('sha256').update(fs.readFileSync(path)).digest('hex');
fs.mkdirSync(out);
const checks = [];
function check(name, fn) { fn(); checks.push(name); }
for (const [name, mask] of [['write-only-create', 0o200], ['read-write-create', 0o600]]) {
  check(name, () => {
    const dest = `${out}/${name}`;
    const file = fs.openSync(dest, 'wx', mask);
    fs.writeSync(file, 'created through open fd\n');
    fs.closeSync(file);
    if (mask & 0o400) assert.equal(mode(dest), mask);
  });
}
check('copyFileSync', () => {
  fs.copyFileSync('/t/src/a.txt', `${out}/copy.txt`);
  assert.equal(fs.readFileSync(`${out}/copy.txt`, 'utf8'), 'alpha\n');
});
check('native cpSync recursive', () => {
  fs.cpSync('/t/src', `${out}/native`, { recursive: true });
  assert.equal(fs.readFileSync(`${out}/native/a.txt`, 'utf8'), 'alpha\n');
  assert.equal(fs.readFileSync(`${out}/native/sub/b.txt`, 'utf8'), 'beta\n');
  assert.equal(mode(`${out}/native/a.txt`), 0o644);
  assert.equal(mode(`${out}/native/sub/b.txt`), 0o640);
});
check('filtered cpSync', () => {
  fs.cpSync('/t/src', `${out}/filtered`, { recursive: true, filter: () => true });
  assert.equal(hash(`${out}/filtered/sub/b.txt`), hash('/t/src/sub/b.txt'));
});
check('20 MiB native copy', () => {
  fs.writeFileSync(`${out}/large.bin`, Buffer.alloc(20 * 1024 * 1024, 0x71));
  fs.cpSync(`${out}/large.bin`, `${out}/large-copy.bin`);
  assert.equal(hash(`${out}/large-copy.bin`), hash(`${out}/large.bin`));
});
console.log(JSON.stringify({version: process.version, checks}));
